45:   async function pdfToMarkdown(file, title, onProgress) {
46:     if (!window.pdfjsLib || !file) return { md: '', pages: 0, chars: 0, headings: [], topics: [], failed: true, reason: 'pdf.js no cargado', meta: {} };
47:     try {
48:       const buf = await file.arrayBuffer();
49:       const pdf = await window.pdfjsLib.getDocument({ data: buf }).promise;
50:       const totalPages = pdf.numPages;
51:       const pages = Math.min(totalPages, 30);
52:       const out = [`# ${title}`, '', `> Convertido desde PDF: ${file.name} · ${totalPages} páginas (${pages} procesadas) · sin subir a terceros.`, ''];
53:       const headings = [];
54:       let chars = 0;
55:       for (let p = 1; p <= pages; p++) {
56:         if (onProgress) onProgress(p, pages);
57:         const page = await pdf.getPage(p);
58:         const tc = await page.getTextContent();
59:         let txt = '';
60:         tc.items.forEach((it, i) => {
61:           const s = String(it.str || '');
62:           if (!s) return;
63:           txt += s;
64:           if (it.hasEOL) txt += '\n';
65:           else if (it.transform && tc.items[i + 1]?.transform && Math.abs(tc.items[i + 1].transform[5] - it.transform[5]) > 3) txt += '\n';
66:           else txt += ' ';
67:         });
68:         const clean = txt.replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n\n').trim();
69:         chars += clean.length;
70:         if (!clean) continue;
71:         out.push(`## Página ${p}`);
72:         const lines = clean.split('\n').map(x => x.trim()).filter(Boolean);
73:         for (const line of lines) {
74:           if (line.length <= 70 && (line === line.toUpperCase() && /[A-ZÁÉÍÓÚÑ]/.test(line) || /^M[óo]dulo/.test(line) || /^Cap[íi]tulo/.test(line))) {
75:             if (headings.length < 20) headings.push(line.slice(0, 80));
76:             out.push(`\n### ${line}\n`);
77:           } else if (line.length > 1) {
78:             out.push(line);
79:           }
80:         }
81:         out.push('');
82:       }
83:       const md = out.join('\n').slice(0, 60000);
84:       const topics = [...new Set((md.toLowerCase().match(/medicin|cbd|thc|riego|ph|ec|vpd|luz|led|plaga|cosec|secad|curad|reprocann|autocultivo|terpen|npk|suelo|compost/g) || []).map(w => w.replace('cosec', 'cosecha').replace('secad', 'secado').replace('curad', 'curado')))].slice(0, 8);
