86:       const meta = { pages: totalPages, processed: pages, chars, headings, topics, year: yearMatch ? Number(yearMatch[0]) : null, lang: 'es-AR' };
87:       if (chars < 80) return { md: '', pages: 0, chars, headings, topics: [], failed: true, reason: 'sin texto extraíble (escaneado?): probar OCR', meta };
88:       return { md, pages: totalPages, chars, headings, topics, failed: false, meta };
89:     } catch (e) {
90:       return { md: '', pages: 0, chars: 0, headings: [], topics: [], failed: true, reason: String(e && e.message || e).slice(0, 120), meta: {} };
